package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
)

type FastScanner struct {
	data []byte
	pos  int
}

func NewFastScanner() *FastScanner {
	data, _ := os.ReadFile("/dev/stdin") // or os.Stdin.Read
	return &FastScanner{data: data}
}

func (s *FastScanner) NextInt64() int64 {
	for s.pos < len(s.data) && (s.data[s.pos] == ' ' || s.data[s.pos] == '\n' || s.data[s.pos] == '\r' || s.data[s.pos] == '\t') {
		s.pos++
	}
	if s.pos >= len(s.data) {
		return 0
	}
	neg := false
	if s.data[s.pos] == '-' {
		neg = true
		s.pos++
	}
	val := int64(0)
	for s.pos < len(s.data) && s.data[s.pos] >= '0' && s.data[s.pos] <= '9' {
		val = val*10 + int64(s.data[s.pos]-'0')
		s.pos++
	}
	if neg {
		return -val
	}
	return val
}

func (s *FastScanner) NextUint64() uint64 {
	for s.pos < len(s.data) && (s.data[s.pos] == ' ' || s.data[s.pos] == '\n' || s.data[s.pos] == '\r' || s.data[s.pos] == '\t') {
		s.pos++
	}
	val := uint64(0)
	for s.pos < len(s.data) && s.data[s.pos] >= '0' && s.data[s.pos] <= '9' {
		val = val*10 + uint64(s.data[s.pos]-'0')
		s.pos++
	}
	return val
}

type Fibonacci struct {
	mod   int64
	cache map[int64]int64
}

func NewFibonacci(mod int64) *Fibonacci {
	f := &Fibonacci{mod: mod, cache: make(map[int64]int64)}
	f.cache[0] = 1
	f.cache[1] = 1
	return f
}

func (f *Fibonacci) Fib(n int64) int64 {
	if v, ok := f.cache[n]; ok {
		return v
	}
	k := n / 2
	var res int64
	if n%2 == 0 {
		fk := f.Fib(k)
		fk1 := f.Fib(k - 1)
