		fk_1 := f.Fib(k - 1)
		res = (fk*fk1 + fk_1*fk) % f.mod
	}
	f.cache[n] = res
	return res
}

func ModPow(a, b, m int64) int64 {
	res := int64(1)
	a %= m
	for b > 0 {
		if b&1 == 1 {
			res = (res * a) % m
		}
		a = (a * a) % m
		b >>= 1
	}
	return res
