		mod:  mod,
		memo: make(map[int64]int64),
	}
	f.memo[0] = 1
	f.memo[1] = 1
	return f
}

func (f *Fibonacci) fib(n int64) int64 {
	if val, ok := f.memo[n]; ok {
		return val
	}
	k := n / 2
	var res int64
	if n%2 == 0 {
		res = (f.fib(k)*f.fib(k) + f.fib(k-1)*f.fib(k-1)) % f.mod
	} else {
		res = (f.fib(k)*f.fib(k+1) + f.fib(k-1)*f.fib(k)) % f.mod
	}
	f.memo[n] = res
	return res
}

func modPow(a, b, m int64) int64 {
	res := int64(1)
	a %= m
	for b > 0 {
		if b&1 == 1 {
			res = (res * a) % m
		}
		a = (a * a) % m
		b >>= 1
	}
	return res
}

