package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
)

var scanner *bufio.Scanner

func init() {
	scanner = bufio.NewScanner(os.Stdin)
	scanner.Split(bufio.ScanWords)
	scanner.Buffer(make([]byte, 1024*1024), 1024*1024)
}

func nextInt64() int64 {
	scanner.Scan()
	val, _ := strconv.ParseInt(scanner.Text(), 10, 64)
	return val
}

type Fibonacci struct {
	mod  int64
	memo map[int64]int64
}

func NewFibonacci(mod int64) *Fibonacci {
	f := &Fibonacci{mod: mod, memo: make(map[int64]int64)}
	f.memo[0] = 1
	f.memo[1] = 1
	return f
}

func (f *Fibonacci) fib(n int64) int64 {
	if val, ok := f.memo[n]; ok {
		return val
	}
	k := n / 2
	var res int64
	if n%2 == 0 {
		fk := f.fib(k)
		fk1 := f.fib(k - 1)
		res = (fk*fk + fk1*fk1) % f.mod
	} else {
		fk := f.fib(k)
		fk1 := f.fib(k + 1)
		fk_1 := f.fib(k - 1)
		res = (fk*fk1 + fk_1*fk) % f.mod
	}
	f.memo[n] = res
	return res
}

func modPow(a, b, m int64) int64 {
	res := int64(1)
	a %= m
	for b > 0 {
		if b&1 == 1 {
			res = (res * a) % m
		}
		a = (a * a) % m
		b >>= 1
	}
	return res
}

func solve() {
	n := nextInt64()
	k := nextInt64()
	l := nextInt64()
	MOD := nextInt64()

	if l < 64 && (uint64(1)<<uint(l))-1 < uint64(k) {
		fmt.Println(0)
		return
	}

	fibCalc := NewFibonacci(MOD)
	zeroPos := fibCalc.fib(n + 1)
	onePos := (modPow(2, n, MOD) - zeroPos) % MOD
	if onePos < 0 {
		onePos += MOD
	}

	res := int64(1)
	for i := int64(0); i < l; i++ {
		if (k>>i)&1 == 1 {
			res = (res * onePos) % MOD
		} else {
			res = (res * zeroPos) % MOD
		}
	}
	fmt.Println(res % MOD)
}

func main() {
	solve()
}

